    """
    Evaluates a mathematical expression using the Shunting Yard algorithm to convert infix notation to postfix and then evaluates the postfix expression.
    Supports +, -, *, /, parentheses, and floating-point numbers, with proper operator precedence.
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operation(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a / b

    def infix_to_postfix(expression):
        output = []
        operators = []
        i = 0
        while i < len(expression):
            if expression[i].isspace():
                i += 1
                continue
            if expression[i].isdigit() or expression[i] == '.':
                num = ''
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                output.append(float(num))
                continue
            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # pop '('
            else:
                while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                    output.append(operators.pop())
                operators.append(expression[i])
            i += 1
        while operators:
            output.append(operators.pop())
        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                result = apply_operation(a, b, token)
                stack.append(result)
        return stack[0]

    postfix_expression = infix_to_postfix(expr)
    return evaluate_postfix(postfix_expression)

